#!/usr/bin/env python3
# Local service website; Python 3 standard library only.
import csv, html, io, json, os, re, secrets, sqlite3, time
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from urllib.parse import parse_qs, urlparse
ROOT=Path(__file__).resolve().parent
DB=Path(os.environ.get('port_DB',ROOT/'data/inquiries.sqlite3'))
DB.parent.mkdir(parents=True,exist_ok=True)
SESSIONS={}
def db():
 c=sqlite3.connect(DB);c.row_factory=sqlite3.Row
 c.execute('CREATE TABLE IF NOT EXISTS inquiries(id INTEGER PRIMARY KEY, created TEXT DEFAULT CURRENT_TIMESTAMP, name TEXT, email TEXT, service TEXT, message TEXT, status TEXT DEFAULT "new")')
 return c
with db():pass
def esc(x):return html.escape(str(x),quote=True)
def shell(title,body):
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{esc(title)} — Ismail Habib</title><meta name="description" content="Practical AI automation, API integration and thoughtful websites by Ismail Habib."><link rel="stylesheet" href="/assets/style.css"></head><body><a class="skip" href="#main">Skip to content</a><header><a class="logo" href="/"><span class="mark">ih.</span>Ismail Habib<span style="font-weight:400;font-size:12px;letter-spacing:0">/ independent developer</span></a><nav aria-label="Main navigation"><a href="/services">Services</a><a href="/about">Approach</a><a href="/contact">Let’s talk <span aria-hidden="true">↗</span></a></nav></header><main id="main" class="wrap">{body}</main><footer><span>Ismail Habib · Independent software development</span><span><a href="/privacy">Data & privacy</a> · <a href="https://en.malt.de/profile/ismailhabib">Malt profile ↗</a></span></footer></body></html>'''
def home():
 return '''<section class="hero"><div><div class="eyebrow"><span class="dot"></span>Practical software. Personal collaboration.</div><h1>Less friction.<br>More <em>possibility.</em></h1><p class="lead">I connect your tools, automate repetitive work and build websites that make the next step feel simple.</p><div class="buttons"><a class="button" href="/contact">Tell me what’s slowing you down <span>↗</span></a></div><a class="textlink" href="/services">Explore how I can help</a></div><div class="system" aria-label="Illustrative integration architecture"><div class="systemtop"><span>CONNECTED BY DESIGN</span><span>01 / 03</span></div><div class="diagram"><div class="node"><strong>▤</strong>Your website</div><div class="connect"></div><div class="node main"><strong>⇄</strong>API & logic</div><div class="connect"></div><div class="node"><strong>✳</strong>Your tools</div></div><div class="systemfoot"><span>Thoughtful connections.<br><b>One clear workflow.</b></span><span class="status">Built around you</span></div><p class="caption">Illustrative architecture · every project starts with your existing systems.</p></div></section><div class="strip"><b>AI & workflow automation</b><span>✳</span><b>API & system integration</b><span>✳</span><b>WordPress & web development</b></div><section class="section"><div class="headingrow"><div><div class="eyebrow">Where I can help</div><h2>A useful next step,<br>wherever you are starting.</h2></div><p class="caption">Build on what works.<br>Improve what gets in the way.</p></div><div class="cards"><article class="card"><span class="num">01 / AUTOMATION</span><h3>Give repetitive work<br>a better workflow.</h3><p>Connect a website to AI features and turn a manual sequence into a clear, reviewable process.</p><a href="/services#automation">AI automation ↗</a></article><article class="card"><span class="num">02 / INTEGRATION</span><h3>Help your systems<br>understand each other.</h3><p>Connect APIs, investigate failed requests and improve the flow between tools you already use.</p><a href="/services#integration">System integration ↗</a></article><article class="card"><span class="num">03 / WEBSITES</span><h3>Make your website<br>work for your business.</h3><p>Build or improve WordPress websites with purposeful layouts, usable forms and useful integrations.</p><a href="/services#web">Web development ↗</a></article></div></section><section class="dark"><div><div class="eyebrow">A direct line from idea to implementation</div><h2>Start with the problem.<br>Find the right-sized solution.</h2></div><div><p>You work directly with me. We clarify what needs to change, agree on the scope and test the result against the way your team actually works.</p><a class="button light" href="/contact">Start a conversation ↗</a></div></section><section class="section"><div class="eyebrow">How we work together</div><h2>Clear steps. Fewer surprises.</h2><div class="steps"><div><span class="num">01 — UNDERSTAND</span><h3>Map the situation</h3><p>Identify the current workflow, its constraints and the outcome you need.</p></div><div><span class="num">02 — BUILD</span><h3>Make the change</h3><p>Implement the agreed scope with practical checkpoints and clear communication.</p></div><div><span class="num">03 — HAND OVER</span><h3>Keep it useful</h3><p>Test the essential paths and leave you with setup and maintenance guidance.</p></div></div></section>'''
def services():
 items=[('automation','01','AI automation','Useful AI, connected to the work around it.','Web interfaces for AI features; backend request processing; workflow automation; troubleshooting across frontend, backend and hosted services.','We define inputs, outputs and the points where a person needs to review the result.'),('integration','02','API & system integration','Make the connection dependable.','External API integration; response and configuration troubleshooting; data mapping; improvements to existing integration logic.','We trace a complete transaction and test both successful and failed requests.'),('web','03','Web development','A website with a clear job to do.','WordPress themes; HTML/CSS layouts; navigation and page structure; forms; backend and AI integrations; ongoing fixes.','We agree on important user journeys and check them on small and large screens.'),('legacy','04','Legacy software modernization','Keep proven software useful.','Reviewing existing C++ Windows code; compatibility changes; Visual Studio debugging; migration verification.','We identify what must keep working and compare behavior before and after changes.')]
 return '<section class="pagehead"><div class="eyebrow">Services</div><h1>Practical help for<br>connected businesses.</h1><p class="lead">A focused improvement or a complete workflow. The scope starts with what you need to achieve.</p></section>'+''.join(f'<section class="section" id="{i}"><div class="dark"><div><div class="eyebrow">{n} / {t}</div><h2>{h}</h2></div><div><p>{d}</p><p>{e}</p><a class="button light" href="/contact?service={i}">Discuss this service ↗</a></div></div></section>' for i,n,t,h,d,e in items)
def contact(token,service='',error=''):
 options=[('automation','AI automation'),('integration','API & system integration'),('web','Web development'),('legacy','Legacy modernization'),('unsure','Help me define the scope')]
 opts=''.join(f'<option value="{v}" {"selected" if v==service else ""}>{t}</option>' for v,t in options)
 return f'''<section class="pagehead"><div class="eyebrow">Start a conversation</div><h1>What could work<br><em>a little better?</em></h1></section><div class="formlayout"><aside><h3>A little context<br>goes a long way.</h3><p class="lead">Tell me about the task, the systems involved and the result you need. You do not need a finished technical brief.</p><p class="caption">This form saves your inquiry to this installation’s inbox. It does not send email. Avoid passwords, access keys or confidential documents.</p><p><a href="https://en.malt.de/profile/ismailhabib">Prefer Malt? View my profile ↗</a></p></aside><section class="formpanel">{f'<div class="notice error" role="alert">{esc(error)}</div>' if error else ''}<form method="post" action="/inquiries"><input type="hidden" name="csrf" value="{token}"><div class="formrow"><div><label for="name">Your name *</label><input id="name" name="name" required maxlength="120" autocomplete="name"></div><div><label for="email">Email address *</label><input id="email" name="email" type="email" required maxlength="254" autocomplete="email"></div></div><label for="service">What can I help with? *</label><select id="service" name="service" required>{opts}</select><label for="message">Tell me about your project *</label><textarea id="message" name="message" required minlength="20" maxlength="5000" placeholder="What happens today, and what would you like to change?"></textarea><div class="honeypot" aria-hidden="true"><label for="website">Leave empty</label><input id="website" name="website" tabindex="-1" autocomplete="off"></div><label class="check"><input type="checkbox" name="consent" value="yes" required><span>I agree to this installation storing my inquiry so it can be reviewed. <a href="/privacy">Read how this works.</a></span></label><button type="submit">Send inquiry <span aria-hidden="true">↗</span></button></form></section></div>'''
class Handler(BaseHTTPRequestHandler):
 def log_message(self,*args):pass
 def token(self):
  cookie=self.headers.get('Cookie','');m=re.search(r'(?:^|;\s*)studio_session=([a-f0-9]+)',cookie);sid=m.group(1) if m else ''
  if sid not in SESSIONS: sid=secrets.token_hex(24);SESSIONS[sid]=(secrets.token_hex(24),time.time())
  self.sid=sid;return SESSIONS[sid][0]
 def send(self,body,status=200,ctype='text/html; charset=utf-8',extra=None):
  body=body.encode() if isinstance(body,str) else body
  self.send_response(status);self.send_header('Content-Type',ctype);self.send_header('Content-Length',str(len(body)));self.send_header('X-Content-Type-Options','nosniff');self.send_header('Cache-Control','no-store');self.send_header('Content-Security-Policy',"default-src 'self'; style-src 'self' 'unsafe-inline'; form-action 'self'; frame-ancestors 'none'; base-uri 'self'")
  if hasattr(self,'sid'):self.send_header('Set-Cookie',f'studio_session={self.sid}; HttpOnly; SameSite=Strict; Path=/')
  for k,v in (extra or {}).items():self.send_header(k,v)
  self.end_headers();self.wfile.write(body)
 def do_GET(self):
  p=urlparse(self.path);q=parse_qs(p.query);token=self.token()
  if p.path=='/assets/style.css':return self.send((ROOT/'assets/style.css').read_bytes(),ctype='text/css')
  if p.path=='/health':return self.send(json.dumps({'status':'ok','storage':'sqlite'}),ctype='application/json')
  if p.path=='/':return self.send(shell('Less friction. More possibility.',home()))
  if p.path=='/services':return self.send(shell('Services',services()))
  if p.path=='/contact':return self.send(shell('Let’s talk',contact(token,q.get('service',[''])[0])))
  if p.path=='/thanks':return self.send(shell('Inquiry saved','<section class="pagehead"><div class="eyebrow">Message received</div><h1>A clearer next step<br>starts here.</h1><div class="notice" role="status">Your inquiry is saved in this installation’s staff inbox.</div><p class="lead">Email delivery is not enabled. Keep a copy of your message if you need it.</p><a class="button" href="/">Back to the website ↗</a></section>'))
  if p.path=='/about':return self.send(shell('Approach','<section class="pagehead"><div class="eyebrow">The person behind the work</div><h1>Hi, I’m Ismail.<br>I make things <em>connect.</em></h1><p class="lead">My work spans AI automation, API integration, existing C++ Windows applications and WordPress websites. The common thread is practical problem-solving across connected systems.</p></section><section class="section"><div class="cards"><article class="card"><h3>Understand first</h3><p>I start with the existing workflow, its constraints and what a useful outcome looks like.</p></article><article class="card"><h3>Build deliberately</h3><p>I work with existing components when they serve the goal and explain the changes that are needed.</p></article><article class="card"><h3>Test the whole path</h3><p>A working component is only part of the result. I check the handoffs between the interface, backend and services.</p></article></div></section>'))
  if p.path=='/privacy':return self.send(shell('Data & privacy','<section class="pagehead"><div class="eyebrow">This installation</div><h1>Your inquiry,<br>handled simply.</h1><p class="lead">The form stores your name, email, selected service, message and submission time in a local SQLite database. A session cookie is used to protect form submissions. No analytics, external fonts or tracking pixels are included.</p><p>This independent project runs locally by default. Inquiries are visible through the local staff inbox and can be exported or deleted there. No email is sent. The operator must define a retention schedule, contact details and an appropriate privacy notice before a public deployment.</p><p>A deployment needs access control and HTTPS; the local staff inbox is deliberately restricted to loopback requests.</p></section>'))
  if p.path in ['/inbox','/export']:
   if self.client_address[0] not in ['127.0.0.1','::1']:return self.send('Local access only',403)
   with db() as c: rows=c.execute('SELECT * FROM inquiries ORDER BY id DESC').fetchall()
   if p.path=='/export':
    out=io.StringIO();w=csv.writer(out);w.writerow(['ID','Created UTC','Name','Email','Service','Message','Status'])
    for row in rows:w.writerow([("'"+str(v)) if str(v).startswith(('=','+','-','@','\t','\r')) else v for v in row])
    return self.send(out.getvalue(),ctype='text/csv; charset=utf-8',extra={'Content-Disposition':'attachment; filename="inquiries.csv"'})
   cards=''.join(f'<article class="inboxcard"><div class="meta">#{x["id"]} · {esc(x["created"])} UTC · <span class="badge">{esc(x["status"])}</span></div><h3>{esc(x["name"])} · {esc(x["service"])}</h3><a href="mailto:{esc(x["email"])}">{esc(x["email"])}</a><p>{esc(x["message"])}</p><form action="/inbox/action" method="post"><input type="hidden" name="csrf" value="{token}"><input type="hidden" name="id" value="{x["id"]}"><button name="action" value="reviewed">Mark reviewed</button> <button name="action" value="delete">Delete inquiry</button></form></article>' for x in rows)
   return self.send(shell('Staff inbox',f'<section class="pagehead"><div class="eyebrow">Local staff workspace</div><h1>Inquiry inbox.</h1><p class="lead">{len(rows)} saved inquiries · data persists across restarts.</p><a class="button" href="/export">Export CSV ↓</a></section>{cards or "<div class=empty>No inquiries yet. Submit the contact form to start a real workflow.</div>"}'))
  self.send(shell('Not found','<section class="pagehead"><h1>That page is not here.</h1><a href="/">Return home</a></section>'),404)
 def do_POST(self):
  token=self.token()
  try:n=int(self.headers.get('Content-Length','0'))
  except ValueError:return self.send('Bad length',400)
  if n>20000:return self.send('Request too large',413)
  data={k:v[0].strip() for k,v in parse_qs(self.rfile.read(n).decode('utf-8'),keep_blank_values=True).items()}
  if not secrets.compare_digest(data.get('csrf',''),token):return self.send('Invalid form session. Reload the form.',403)
  if self.path=='/inbox/action':
   if self.client_address[0] not in ['127.0.0.1','::1']:return self.send('Local access only',403)
   try:ident=int(data.get('id','0'))
   except ValueError:return self.send('Invalid inquiry',400)
   with db() as c:
    if data.get('action')=='delete':c.execute('DELETE FROM inquiries WHERE id=?',(ident,))
    elif data.get('action')=='reviewed':c.execute('UPDATE inquiries SET status="reviewed" WHERE id=?',(ident,))
    else:return self.send('Unknown action',400)
   return self.send('',303,extra={'Location':'/inbox'})
  if self.path!='/inquiries':return self.send('Not found',404)
  if data.get('website'):return self.send('Submission rejected',400)
  if not (1<=len(data.get('name',''))<=120 and re.fullmatch(r'[^\s@]+@[^\s@]+\.[^\s@]+',data.get('email','')) and len(data.get('email',''))<=254 and data.get('service') in ['automation','integration','web','legacy','unsure'] and 20<=len(data.get('message',''))<=5000 and data.get('consent')=='yes'):
   return self.send(shell('Check your inquiry',contact(token,error='Please provide a name, valid email, service and project message of 20–5,000 characters, and agree to storage.')),400)
  with db() as c:c.execute('INSERT INTO inquiries(name,email,service,message) VALUES(?,?,?,?)',tuple(data[k] for k in ['name','email','service','message']))
  self.send('',303,extra={'Location':'/thanks'})
if __name__=='__main__':
 port=int(os.environ.get('PORT','8107'));print(f'Website: http://127.0.0.1:{port} | Staff inbox: /inbox',flush=True);ThreadingHTTPServer(('127.0.0.1',port),Handler).serve_forever()
